const body = $input.first().json.body || {};
const { from, to } = body;
if (!from || !to) throw new Error("Missing from/to dates");

const filled = [], skipped = [], failed = [];
const existingReports = ((await (await fetch('http://mock-api:4100/report')).json().catch(() => ({}))).data || []);
const rates = ((await (await fetch('http://mock-api:4100/rates')).json().catch(() => ({}))).rates || { MYR: 1, USD: 4.42, SGD: 3.28 });

let cur = new Date(`${from}T00:00:00Z`);
const end = new Date(`${to}T00:00:00Z`);

while (cur <= end) {
  const dateStr = cur.toISOString().slice(0, 10);
  cur.setUTCDate(cur.getUTCDate() + 1);

  if (existingReports.some(r => String(r.date) === dateStr)) {
    skipped.push({ date: dateStr, reason: "report already exists" });
    continue;
  }

  const fromMs = Date.parse(`${dateStr}T00:00:00+08:00`);
  const fromISO = new Date(fromMs).toISOString();
  const toISO = new Date(fromMs + 86400000).toISOString();

  let page = 1, totalPages = 1, dayOrders = [], fetchErr = null;
  try {
    do {
      const res = await fetch(`http://mock-api:4100/orders?from=${fromISO}&to=${toISO}&page=${page}&per_page=100`);
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        fetchErr = err.error || `HTTP ${res.status}`;
        break;
      }
      const data = await res.json();
      dayOrders.push(...(data.data || []));
      totalPages = data.total_pages || 1;
      page++;
    } while (page <= totalPages);
  } catch (err) {
    fetchErr = String(err);
  }

  if (fetchErr) {
    failed.push({ date: dateStr, reason: fetchErr });
    continue;
  }

  if (dayOrders.length === 0) {
    skipped.push({ date: dateStr, reason: "no orders on this day" });
    continue;
  }

  const totalMYR = Number(dayOrders.reduce((sum, o) => sum + o.amount * (rates[o.currency] || 1), 0).toFixed(2));
  const newReport = { date: dateStr, order_count: dayOrders.length, total_myr: totalMYR };

  const postRes = await fetch('http://mock-api:4100/report', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(newReport)
  });

  if (postRes.ok) {
    filled.push(dateStr);
    existingReports.push(newReport);
  } else {
    failed.push({ date: dateStr, reason: `HTTP ${postRes.status}` });
  }
}

return [{ json: { filled, skipped, failed } }];
